"use client";

import { useState, useEffect } from "react";
import Image from "next/image";
import {
  Shield, AlertTriangle, FileText, Upload, Wallet,
  TrendingUp, Sparkles, ArrowRight, Activity, Search,
  Eye, EyeOff, Lock, Globe, History, ChevronRight, X
} from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { extractTextFromPDF } from "@/lib/pdf-parser";
import { AnalysisResult } from "@/types";

import FileUpload from "@/components/FileUpload";
import WealthChart from "@/components/WealthChart";
import RoastCard from "@/components/RoastCard";
import DebugPanel from "@/components/DebugPanel";
import SpendingBreakdown from "@/components/SpendingBreakdown";

import { analyzeStatementAPI } from "@/lib/api";

export default function Dashboard() {
  const [file, setFile] = useState<File | null>(null);
  const [rawText, setRawText] = useState("");
  const [loading, setLoading] = useState(false);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [roast, setRoast] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<"pdf" | "text">("pdf");
  const [privacyMode, setPrivacyMode] = useState(false);
  const [balance, setBalance] = useState(0);

  // For the Chart
  const [wealthData, setWealthData] = useState<any[]>([]);
  const [rawDump, setRawDump] = useState<any>(null);
  const [cleanedDump, setCleanedDump] = useState<any>(null);

  useEffect(() => {
    if (analysis) {
      const total = analysis.transactions
        .filter(t => t.transaction_type === "DEBIT")
        .reduce((s, t) => s + t.amount, 0);
      setBalance(total);
    }
  }, [analysis]);

  const handleAnalyze = async () => {
    setLoading(true);
    setError(null);
    try {
      let data;
      if (activeTab === "pdf") {
        if (!file) throw new Error("Please select a statement first.");
        const text = await extractTextFromPDF(file);
        if (!text || text.trim().length < 50) {
          throw new Error("Could not extract enough text from PDF.");
        }
        data = await analyzeStatementAPI(text);
      } else {
        if (!rawText.trim()) throw new Error("Please paste some transactions first.");
        data = await analyzeStatementAPI(rawText);
      }

      setAnalysis(data.analysis);
      setRoast(data.roast);
      setRawDump(data.raw_data || "No raw signal captured.");
      setCleanedDump(data.analysis);

      // Regret Calculation: 1.3x multiplier for invested fantasy
      const monthlyWaste = data.analysis.transactions
        .filter((t: any) => t.is_impulsive)
        .reduce((sum: number, t: any) => sum + t.amount, 0);

      setWealthData([
        { year: 'Reality', value: monthlyWaste * 12, type: 'spent' },
        { year: 'Fantasy', value: Math.round(monthlyWaste * 12 * 1.3), type: 'invested' }
      ]);

    } catch (err: any) {
      setError(err.message || "Analysis failed.");
    } finally {
      setLoading(false);
    }
  };

  const clear = () => {
    setAnalysis(null);
    setRoast("");
    setFile(null);
    setRawText("");
    setWealthData([]);
  };

  return (
    <main className="min-h-screen bg-transparent grid-lines custom-scrollbar overflow-x-hidden relative">
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute top-[-10%] left-[-10%] w-[45%] h-[45%] bg-primary/10 rounded-full blur-[150px] animate-pulse" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[45%] h-[45%] bg-secondary/10 rounded-full blur-[150px] animate-pulse" />
      </div>

      <nav className="border-b-[4px] border-black bg-white p-6 sticky top-0 z-[100] shadow-brutalist">
        <div className="max-w-7xl mx-auto flex items-center justify-between">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-8">
              <Image
                src="/assets/rupee-roast/logo.png"
                alt="Piggy Stash"
                width={64}
                height={64}
                className="w-16 h-16 pixel-antialiased drop-shadow-lg"
              />
              <h1 className="text-3xl text-black font-arcade tracking-tighter leading-none">
                RUPEE<br /><span className="text-primary drop-shadow-[2px_2px_0px_#000]">ROAST</span>
              </h1>
            </div>
          </div>

          <div className="hidden md:flex items-center gap-6">
            {['UPLOAD', 'ROASTS', 'HALL OF SHAME'].map((item) => (
              <button key={item} className="arcade-btn !py-4 !px-8 border-2">
                {item}
              </button>
            ))}
          </div>

          <div className="flex items-center gap-6">
            <div className="yellow-card px-6 py-2 font-arcade text-[10px] border-2 shadow-brutalist-sm">
              CREDITS: 99
            </div>
            <div className="w-12 h-12 bg-black rounded-none border-2 border-primary flex items-center justify-center">
              <div className="w-4 h-4 bg-primary animate-pulse" />
            </div>
          </div>
        </div>
      </nav>

      <div className="max-w-7xl mx-auto px-6 py-12 space-y-12">

        {/* 3. HERO SECTION: The "Verdict" Terminal */}
        <section className="relative">
          <motion.div
            initial={{ scale: 0.98, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="indigo-card !bg-[#0A0A1A] p-12 md:p-16 overflow-hidden crt-overlay border-[4px] shadow-brutalist-lg"
          >
            <div className="relative z-10 grid grid-cols-1 lg:grid-cols-12 gap-12 items-center">
              <div className="lg:col-span-12 mb-8">
                <div className="flex items-center gap-6 mb-6">
                  <div className="w-4 h-4 rounded-full bg-primary animate-ping" />
                  <span className="font-arcade text-xs text-primary tracking-widest">LIVE_ANALYSIS_PROTOCOL_v0.9</span>
                </div>
                <h2 className="text-5xl md:text-8xl text-white font-arcade leading-tight text-center lg:text-left tracking-tighter">
                  VERDICT: <span className="text-secondary drop-shadow-[4px_4px_0px_#000]">FATAL</span>
                </h2>
              </div>

              <div className="lg:col-span-8 relative">
                <div className="comic-bubble text-black font-mono font-bold text-2xl leading-relaxed p-14 mt-8 mb-12 shadow-brutalist-lg border-[4px] bg-white">
                  <div className="absolute -top-16 -right-16">
                    <Image
                      src="/assets/rupee-roast/sticker_crying_wallet.png"
                      alt="Crying Wallet"
                      width={192}
                      height={192}
                      className="w-48 h-48 rotate-12 drop-shadow-2xl"
                    />
                  </div>
                  {roast || "WAITING FOR SIGNAL... DEPOSIT YOUR CAPITAL RECORDS TO INITIATE FORENSIC SHAME PROTOCOL."}
                </div>
              </div>

              <div className="lg:col-span-4 flex justify-center">
                <motion.div
                  animate={{ rotate: [3, -3, 3] }}
                  transition={{ duration: 4, repeat: Infinity }}
                  className="yellow-card p-12 rotate-3 shadow-brutalist-lg border-[4px] bg-white text-black"
                >
                  <p className="font-arcade text-[12px] text-center mb-8">SHAME_SCORE</p>
                  <p className="text-9xl font-black text-center tabular leading-none">
                    {analysis ? analysis.financial_health_score : "00"}
                  </p>
                </motion.div>
              </div>
            </div>
          </motion.div>
        </section>

        {/* 4. THE CORE FEATURE: The "Regret Engine" */}
        {analysis && (
          <section className="grid grid-cols-1 lg:grid-cols-2 gap-0 border-[4px] border-black shadow-brutalist-lg overflow-hidden group bg-black">
            <div className="bg-[#0A0A1A] p-16 border-b-[4px] lg:border-b-0 lg:border-r-[4px] border-black relative overflow-hidden">
              <div className="absolute top-0 right-0 p-12 opacity-30 pointer-events-none group-hover:scale-125 transition-transform duration-1000">
                <Image
                  src="/assets/rupee-roast/dumpster_fire.png"
                  alt="Dumpster Fire"
                  width={400}
                  height={400}
                  className="w-[400px] h-[400px]"
                />
              </div>
              <div className="relative z-10 space-y-10">
                <h3 className="font-arcade text-secondary text-3xl drop-shadow-[2px_2px_0px_#000]">THE REALITY<br /><span className="text-white text-xs opacity-50 tracking-widest">(Capital Burned)</span></h3>
                <div className="space-y-4">
                  <p className="text-xs font-arcade text-white/40 uppercase">Burn Status: CRITICAL</p>
                  <p className="text-8xl font-black text-white tabular drop-shadow-2xl">₹{balance.toLocaleString()}</p>
                </div>
                <div className="pink-card !p-8 font-mono font-bold text-xl border-[3px] shadow-brutalist">
                  "MOSTLY SPENT ON: VIBES & FAST FOOD."
                </div>
              </div>
            </div>

            <div className="bg-white p-16 relative overflow-hidden text-black transition-all duration-500 group-hover:bg-[#F0FF00]">
              <div className="absolute top-0 right-0 p-12 opacity-30 pointer-events-none group-hover:translate-x-12 group-hover:-translate-y-12 transition-transform duration-1000">
                <Image
                  src="/assets/rupee-roast/rocket.png"
                  alt="Rocket"
                  width={400}
                  height={400}
                  className="w-[400px] h-[400px]"
                />
              </div>
              <div className="relative z-10 space-y-10">
                <h3 className="font-arcade text-primary drop-shadow-[3px_3px_0px_#000] text-3xl">THE FANTASY<br /><span className="text-black text-xs opacity-50 tracking-widest">(If Invested)</span></h3>
                <div className="space-y-8">
                  <div>
                    <p className="text-xs font-arcade text-black/40 uppercase">Projected Net Worth</p>
                    <p className="text-8xl font-black text-black tabular">₹{Math.round(balance * 1.3).toLocaleString()}</p>
                  </div>
                  <button className="lime-card !p-10 font-arcade text-md w-full mt-10 border-[4px] shadow-brutalist-lg hover:bg-black hover:text-primary transition-all active:scale-95 text-center">
                    STOP THE BLEEDING. START INVESTING.
                  </button>
                </div>
              </div>
            </div>
          </section>
        )}

        <div className="grid grid-cols-1 lg:grid-cols-12 gap-16 items-start">
          {/* Controls - The HUD */}
          <section className="lg:col-span-5 space-y-16">
            <div className="brutalist-card p-14 !bg-white text-black border-[4px] shadow-brutalist-lg">
              <div className="flex items-center gap-6 mb-12">
                <div className="w-8 h-8 bg-black border-[3px] border-primary shadow-brutalist-sm" />
                <span className="font-arcade text-[12px] tracking-widest">INGESTION_MODULE_V2.0</span>
              </div>

              <div className="flex bg-black p-2 mb-12 border-[4px] border-black text-white">
                <button
                  onClick={() => setActiveTab("pdf")}
                  className={`flex-1 flex items-center justify-center gap-4 py-6 font-arcade text-[10px] transition-all ${activeTab === "pdf"
                    ? "bg-primary text-black"
                    : "text-white/40 hover:text-white"
                    }`}
                >
                  <Upload className="w-5 h-5" /> STATEMENT
                </button>
                <button
                  onClick={() => setActiveTab("text")}
                  className={`flex-1 flex items-center justify-center gap-4 py-6 font-arcade text-[10px] transition-all ${activeTab === "text"
                    ? "bg-secondary text-white"
                    : "text-white/40 hover:text-white"
                    }`}
                >
                  <FileText className="w-5 h-5" /> RAW_LOGS
                </button>
              </div>

              <AnimatePresence mode="wait">
                {activeTab === "pdf" ? (
                  <motion.div key="pdf" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
                    <FileUpload onFileSelect={(f) => setFile(f)} />
                  </motion.div>
                ) : (
                  <motion.div key="text" initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}>
                    <textarea
                      placeholder="PASTE YOUR CAPITAL FLUX HERE..."
                      value={rawText}
                      onChange={(e) => setRawText(e.target.value)}
                      className="w-full h-80 p-8 bg-black border-[4px] border-black text-primary placeholder:text-white/20 focus:border-primary transition-all outline-none resize-none font-mono font-bold text-lg custom-scrollbar shadow-inner"
                    />
                  </motion.div>
                )}
              </AnimatePresence>

              <button
                onClick={handleAnalyze}
                disabled={loading}
                className="w-full mt-12 lime-card py-10 font-arcade text-xl shadow-brutalist-lg active:shadow-brutalist border-[4px] flex items-center justify-center gap-10 group"
              >
                {loading ? (
                  <div className="flex items-center gap-8">
                    <div className="w-8 h-8 border-[6px] border-black border-t-transparent animate-spin" />
                    <span>EXTRACTING_DNA...</span>
                  </div>
                ) : (
                  <>
                    <span>INITIATE ROAST</span>
                    <ArrowRight className="w-8 h-8 group-hover:translate-x-4 transition-transform" />
                  </>
                )}
              </button>

              {error && (
                <div className="mt-10 p-10 pink-card text-xs font-arcade leading-relaxed border-[4px] shadow-neon-pink">
                  ERROR: SYSTEM_FAILED ( {error} )
                </div>
              )}
            </div>

            <div className="grid grid-cols-2 gap-8">
              <div className="brutalist-card p-10 !bg-white text-black text-center border-[4px] shadow-brutalist">
                <Shield className="w-12 h-12 text-primary mx-auto mb-6 drop-shadow-md" />
                <p className="font-arcade text-[12px]">ENCRYPTED</p>
              </div>
              <div className="brutalist-card p-10 !bg-white text-black text-center border-[4px] shadow-brutalist">
                <Lock className="w-12 h-12 text-secondary mx-auto mb-6 drop-shadow-md" />
                <p className="font-arcade text-[12px]">SECURE_TUNNEL</p>
              </div>
            </div>
          </section>

          {/* Visualization - The Receipt */}
          <section className="lg:col-span-7">
            {analysis ? (
              <div className="space-y-20 pb-40">
                <div className="flex items-center gap-8 mb-12">
                  <div className="w-4 h-16 bg-primary shadow-brutalist-sm" />
                  <h3 className="font-arcade text-white text-2xl tracking-tight">RECEIPT OF SHAME</h3>
                </div>
                <SpendingBreakdown analysis={analysis} />

                <div className="brutalist-card p-14 bg-white border-[4px] shadow-brutalist-lg relative overflow-hidden">
                  <div className="absolute top-0 right-0 p-16 opacity-10 pointer-events-none">
                    <TrendingUp className="w-80 h-80 text-black" />
                  </div>
                  <div className="mb-14 relative z-10 border-b-4 border-black pb-10">
                    <h4 className="font-arcade text-2xl mb-6 text-black tracking-tighter">WEALTH TRAJECTORY</h4>
                    <p className="font-mono text-md text-black font-black uppercase tracking-widest opacity-60">FORENSIC PROJECTION OF YOUR WASTED POTENTIAL.</p>
                  </div>
                  <div className="h-[450px] relative z-10">
                    <WealthChart data={wealthData} />
                  </div>
                </div>

                <DebugPanel raw={rawDump} cleaned={cleanedDump} />

                <button
                  onClick={clear}
                  className="w-full text-center py-24 font-arcade text-[11px] text-white/20 hover:text-red-500 transition-all cursor-pointer tracking-[1.5em]"
                >
                  [ EMERGENCY_ERASE_ALL_LOGS ]
                </button>
              </div>
            ) : (
              <div className="h-full min-h-[800px] border-[5px] border-dashed border-white/20 flex flex-col items-center justify-center text-center p-24 bg-white/[0.03] shadow-inner rounded-3xl">
                <div className="relative mb-12">
                  <Search className="w-32 h-32 text-white/5 mb-8" />
                  <div className="absolute inset-0 bg-primary/10 blur-[80px] rounded-full animate-pulse" />
                </div>
                <h3 className="font-arcade text-white text-3xl mb-8 text-primary drop-shadow-[4px_4px_0px_#000] tracking-tighter">SYSTEM_IDLE</h3>
                <p className="text-white/40 font-mono text-xl max-w-md font-black uppercase tracking-[0.2em] leading-relaxed">
                  AWAITING UPI DATA SIGNAL. INSERT STATEMENT TO BEGIN THE ROAST PROTOCOL.
                </p>
              </div>
            )}
          </section>
        </div>
      </div>

      {/* Footer */}
      <footer className="border-t-[4px] border-black bg-white py-24 px-8 font-arcade text-[10px] text-black">
        <div className="max-w-7xl mx-auto flex flex-col md:flex-row justify-between items-center gap-12">
          <div className="space-y-6 text-center md:text-left">
            <p className="text-black font-bold text-lg">RUPEE ROAST V1.2 - BUILD: HIGH_VOLTAGE_99</p>
            <p className="opacity-60 text-xs">© 2026 ELITE CAPITAL FORENSICS. ALL REGRETS RESERVED.</p>
          </div>
          <div className="flex gap-16 underline decoration-2 underline-offset-8">
            <a href="#" className="hover:text-primary transition-all">TERMINAL</a>
            <a href="#" className="hover:text-secondary transition-all">PRIVACY</a>
            <a href="#" className="hover:text-accent transition-all">SHELL</a>
          </div>
        </div>
      </footer>
    </main>
  );
}

"use client";

import { useState, useRef } from "react";
import { Upload, X, FileCheck, Shield, Lock } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";

interface FileUploadProps {
    onFileSelect: (file: File | null) => void;
}

export default function FileUpload({ onFileSelect }: FileUploadProps) {
    const [file, setFile] = useState<File | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleDragOver = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = () => {
        setIsDragging(false);
    };

    const handleDrop = (e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const droppedFile = e.dataTransfer.files[0];
        if (droppedFile && droppedFile.type === "application/pdf") {
            setFile(droppedFile);
            onFileSelect(droppedFile);
        }
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const selectedFile = e.target.files?.[0];
        if (selectedFile) {
            setFile(selectedFile);
            onFileSelect(selectedFile);
        }
    };

    const clearFile = (e: React.MouseEvent) => {
        e.stopPropagation();
        setFile(null);
        onFileSelect(null);
        if (fileInputRef.current) fileInputRef.current.value = "";
    };

    return (
        <div
            onClick={() => fileInputRef.current?.click()}
            onDragOver={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            className={`
                relative group cursor-pointer overflow-hidden p-10 transition-all duration-100 brutalist-card !bg-black text-white
                ${isDragging ? "!bg-primary !text-black -translate-x-1 -translate-y-1" : "hover:border-primary/40"}
            `}
        >
            <input
                type="file"
                ref={fileInputRef}
                onChange={handleChange}
                className="hidden"
                accept="application/pdf"
            />

            <div className="relative z-10 flex flex-col items-center text-center gap-6">
                <div className={`w-16 h-16 border-[3px] border-black shadow-brutalist-sm flex items-center justify-center transition-colors duration-100 ${isDragging || file ? 'bg-white text-black' : 'bg-primary text-black'}`}>
                    {isDragging ? (
                        <Shield className="w-8 h-8 animate-bounce" />
                    ) : file ? (
                        <FileCheck className="w-8 h-8" />
                    ) : (
                        <Upload className="w-8 h-8" />
                    )}
                </div>

                <AnimatePresence mode="wait">
                    {!file ? (
                        <motion.div
                            key="empty"
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            className="space-y-3"
                        >
                            <h3 className="font-arcade text-xs">
                                {isDragging ? "RELEASE TO INGEST" : "INSERT STATEMENT"}
                            </h3>
                            <p className="font-mono text-[9px] font-bold text-white/40 uppercase tracking-widest">
                                1P START - PDF ONLY
                            </p>
                            <div className="pt-4 flex items-center justify-center gap-4">
                                <div className="w-6 h-[2px] bg-white/10" />
                                <Lock className="w-3 h-3 text-secondary" />
                                <div className="w-6 h-[2px] bg-white/10" />
                            </div>
                        </motion.div>
                    ) : (
                        <motion.div
                            key="file"
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            className="space-y-4"
                        >
                            <div className="px-4 py-1 bg-primary text-black font-arcade text-[6px] shadow-brutalist-sm inline-block">
                                DATA_SECURED_V1
                            </div>
                            <h3 className="font-mono font-bold text-md tracking-tight truncate max-w-[200px] mx-auto">
                                {file.name.toUpperCase()}
                            </h3>
                            <button
                                onClick={clearFile}
                                className="font-arcade text-[7px] text-secondary hover:underline"
                            >
                                [ EJECT_MODULE ]
                            </button>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
        </div>
    );
}

"use client";

import { motion } from "framer-motion";
import ReactMarkdown from "react-markdown";
import { ShieldAlert, Activity, Fingerprint } from "lucide-react";
import Image from "next/image";

interface RoastCardProps {
    roast: string;
}

export default function RoastCard({ roast }: RoastCardProps) {
    return (
        <motion.div
            initial={{ opacity: 0, scale: 0.98 }}
            animate={{ opacity: 1, scale: 1 }}
            className="brutalist-card !bg-white p-12 md:p-16 relative group overflow-hidden border-[4px] shadow-brutalist-lg"
        >
            {/* Tactical Decal */}
            <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
                <Fingerprint className="w-64 h-64 text-black" />
            </div>

            <div className="relative z-10 flex flex-col md:flex-row gap-12 items-start">
                <div className="shrink-0 flex flex-col items-center">
                    <div className="w-24 h-24 bg-secondary rounded-none border-[4px] border-black flex items-center justify-center shadow-brutalist relative">
                        <ShieldAlert className="w-12 h-12 text-white" />
                    </div>
                    <div className="mt-10 text-center space-y-6">
                        <span className="block font-arcade text-[10px] text-black/40 uppercase tracking-widest">Audit Log</span>
                        <div className="px-6 py-3 bg-black border-[3px] border-black flex items-center gap-4">
                            <div className="w-3 h-3 bg-primary animate-pulse" />
                            <span className="font-arcade text-[9px] text-primary uppercase tracking-widest">Active</span>
                        </div>
                    </div>
                </div>

                <div className="flex-1 max-w-none text-black overflow-hidden font-mono">
                    <ReactMarkdown
                        components={{
                            p: ({ children }) => <p className="text-2xl font-black leading-relaxed text-black mb-10 tracking-tight">{children}</p>,
                            strong: ({ children }) => <strong className="text-secondary font-black underline decoration-4 underline-offset-8">{children}</strong>,
                            li: ({ children }) => (
                                <motion.li
                                    initial={{ opacity: 0, x: -10 }}
                                    whileInView={{ opacity: 1, x: 0 }}
                                    className="text-xl text-black/80 font-bold mb-6 flex gap-6 items-start before:content-['>>'] before:text-primary before:font-black"
                                >
                                    {children}
                                </motion.li>
                            ),
                            ul: ({ children }) => <ul className="list-none p-0 my-10 space-y-4">{children}</ul>,
                            h2: ({ children }) => <h2 className="font-arcade text-lg text-secondary mt-16 mb-8 border-b-[4px] border-secondary/10 pb-4 tracking-tighter">{children}</h2>
                        }}
                    >
                        {roast}
                    </ReactMarkdown>
                </div>
            </div>

            <div className="mt-12 pt-8 border-t-[2px] border-white/10 flex justify-between items-center relative z-10">
                <div className="flex items-center gap-4">
